/* Shared fictional teaching records for the public V3 Field Guide. Not a verified company risk register. */
window.SDLCRiskRecords=[{"id":"R10","title":"AI-assisted requirements omit critical constraints","domain":"Design & planning","group":"Design & planning","relevance":"AI-amplified","plainEnglish":"An AI-produced requirement or task plan misses a security, reliability, or business constraint, and the omission propagates into implementation.","why":"Design output may sound complete despite missing domain assumptions. Agents can distribute the same omission through tickets, code, and tests.","challenge":"Can the design process reveal a missing authorization, privacy, or failure-handling requirement before work begins?","monitor":"Compare generated requirements to authoritative constraints, solicit domain review, and track downstream rework.","respond":"Escalate incomplete requirements, correct the design baseline, and revisit dependent changes.","stages":["Design & planning"],"riskEvent":"An AI-produced requirement or task plan misses a security, reliability, or business constraint, and the omission propagates into implementation.","objective":"Requirements and designs used for consequential work should be checked against authoritative stakeholder constraints, not only AI-generated summaries.","securityBoundary":"An agent-generated specification is an input to engineering judgment, not the definitive requirements source.","inspect":"Compare the original request, design artifacts, relevant standards, and approved acceptance criteria.","negativeTest":"Introduce an omitted security constraint into a fictional request; determine whether design review identifies it.","failure":"Requirement gaps may survive into implementation or tests.","evidence":"Traceability from stakeholder constraints to approved design and acceptance criteria.","operations":"Compare generated requirements to authoritative constraints, solicit domain review, and track downstream rework.","incidentResponse":"Escalate incomplete requirements, correct the design baseline, and revisit dependent changes.","approaches":[["Human-authored requirements","Keep a domain owner responsible for scope and acceptance criteria."],["AI draft with structured review","Use AI for first-pass decomposition but review assumptions and omissions."],["Automated requirement cross-check","Compare drafts to approved constraints; does not replace domain expertise."]],"sourceStatement":"Fictional design agent decomposes a feature into tasks and acceptance criteria.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Design & planning","otherApplicable":[],"downstreamEffects":["Coding & tool execution","Testing & validation","Review & approval"],"theme":"Requirements & design","crossCutting":false},{"id":"R11","title":"AI architecture recommendation hides a critical tradeoff","domain":"Design & planning","group":"Design & planning","relevance":"AI-amplified","plainEnglish":"A design agent proposes an apparently simpler architecture that conceals an availability, security, scalability, or ownership tradeoff.","why":"AI can generate plausible solution paths from incomplete operating context; persuasive recommendations may obscure constraints or existing alternatives.","challenge":"What architectural assumption would reverse the proposed recommendation?","monitor":"Review assumption coverage, alternative comparison, load/security evidence, and decisions changed after review.","respond":"Reopen the decision when a critical assumption is falsified; assign management ownership for the tradeoff.","stages":["Design & planning"],"riskEvent":"A design agent proposes an apparently simpler architecture that conceals an availability, security, scalability, or ownership tradeoff.","objective":"Consequential AI-assisted architecture choices should identify assumptions, constraints, alternatives, and accountable decision makers.","securityBoundary":"A generated design is advisory unless an authorized process explicitly delegates implementation or approval.","inspect":"Review design rationale, dependency diagrams, threat models, cost estimates and decision logs.","negativeTest":"Vary one hidden constraint, such as tenant isolation, and see whether the proposal changes appropriately.","failure":"An attractive design proves incompatible with a requirement discovered later.","evidence":"Reviewed architecture decision record, independent checks, and recorded exceptions.","operations":"Review assumption coverage, alternative comparison, load/security evidence, and decisions changed after review.","incidentResponse":"Reopen the decision when a critical assumption is falsified; assign management ownership for the tradeoff.","approaches":[["Human architecture review","Use established engineering architecture reviews for high-impact decisions."],["Design-option comparison","Require explicit alternatives and reasons for rejection."],["Targeted executable spike","Validate uncertain performance and security assumptions before commitment."]],"sourceStatement":"Fictional architecture agent recommends a new shared service.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Design & planning","otherApplicable":[],"downstreamEffects":["Coding & tool execution","Build & release","Production & operations"],"theme":"Requirements & design","crossCutting":false},{"id":"R12","title":"Untrusted context redirects an agent's tool use","domain":"Coding & tool execution","group":"Coding & tool execution","relevance":"Agent-specific","plainEnglish":"Instructions hidden in repository files, issues, documentation, or tool output cause an agent to perform an unintended action.","why":"An agent can interpret task data as instructions while acting through tool credentials. The dangerous boundary is between untrusted content and authorized actions.","challenge":"Can a malicious comment or tool response change which files the agent edits or which commands it executes?","monitor":"Track anomalous tool calls, untrusted-source encounters, and attempted out-of-scope actions.","respond":"Stop the tool session, restrict credentials and investigate modified artifacts and accessed data.","stages":["Coding & tool execution","Design & planning","Testing & validation","Review & approval","Build & release","Production & operations"],"riskEvent":"Instructions hidden in repository files, issues, documentation, or tool output cause an agent to perform an unintended action.","objective":"Agent tool use must stay within authorized task scope regardless of instructions found in untrusted material.","securityBoundary":"Treat retrieved content and repository data as lower-trust inputs, not permissions to expand agent authority.","inspect":"Inspect instruction hierarchy, isolation, effective CLI/API scopes, and enforcement outside the prompt.","negativeTest":"Insert an obvious malicious instruction in a fictional issue; attempt out-of-scope file modification or network access.","failure":"Agent follows external instructions instead of the authorized task.","evidence":"Tool logs, denied action records, source-to-action correlation and isolated execution traces.","operations":"Track anomalous tool calls, untrusted-source encounters, and attempted out-of-scope actions.","incidentResponse":"Stop the tool session, restrict credentials and investigate modified artifacts and accessed data.","approaches":[["Narrow tool access","Grant only task-relevant tools and permissions."],["Enforce external policy","Restrict operations independently of model compliance."],["Untrusted-input evaluation","Run representative injection tests and examine what the agent actually attempted."]],"sourceStatement":"Fictional coding agent consumes a pull-request comment containing adversarial instructions.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Coding & tool execution","otherApplicable":[{"stage":"Design & planning","condition":"If planning agents process untrusted content and act with tools."},{"stage":"Testing & validation","condition":"If test agents process untrusted content and act with tools."},{"stage":"Review & approval","condition":"If review agents process untrusted comments and act with tools."},{"stage":"Build & release","condition":"If build agents process untrusted data and act with tools."},{"stage":"Production & operations","condition":"If operations agents process untrusted alerts and act with tools."}],"downstreamEffects":[],"theme":"Untrusted instructions","crossCutting":true},{"id":"R13","title":"Agent's effective tool permissions exceed task authority","domain":"Coding & tool execution","group":"Coding & tool execution","relevance":"Agent-specific","plainEnglish":"A coding agent can read sensitive files, change protected configuration, or invoke production-adjacent tools unrelated to its assigned task.","why":"Delegation through IDEs, CLIs, services, and MCP tools creates a difference between task intent and actual credential reach.","challenge":"Could the same agent credential alter CI configuration or access secrets while working on a small documentation fix?","monitor":"Reconcile granted scopes, tool invocations, privilege changes and unexpected access attempts.","respond":"Disable overbroad tool paths, rotate exposed credentials where necessary, and re-scope delegation.","stages":["Coding & tool execution","Testing & validation","Review & approval","Build & release","Production & operations"],"riskEvent":"A coding agent can read sensitive files, change protected configuration, or invoke production-adjacent tools unrelated to its assigned task.","objective":"Execution permissions should be bounded to justified tasks and independently checked for consequential actions.","securityBoundary":"Do not rely on natural-language instructions as the only constraint on powerful filesystem, API, or cloud tools.","inspect":"Inspect service identities, tokens, MCP exposure, CLI environment, sandbox boundaries and alternate routes.","negativeTest":"Assign a trivial task, then attempt to modify protected CI or retrieve a synthetic secret using available tools.","failure":"A low-risk task grants access capable of high-impact actions.","evidence":"Effective permission inventory, tool call records and denied boundary tests.","operations":"Reconcile granted scopes, tool invocations, privilege changes and unexpected access attempts.","incidentResponse":"Disable overbroad tool paths, rotate exposed credentials where necessary, and re-scope delegation.","approaches":[["Constrained workspace","Isolate changes from protected configuration and secrets."],["Short-lived credentials","Issue task-scoped access with expiry."],["Purpose-bound tool gateway","Authorize specific actions with higher complexity and maintenance."]],"sourceStatement":"Fictional code-writing agent runs shell commands through an IDE plugin.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Coding & tool execution","otherApplicable":[{"stage":"Testing & validation","condition":"If test agents have execution credentials."},{"stage":"Review & approval","condition":"If review agents have effective privileged credentials."},{"stage":"Build & release","condition":"If release agents have deploy or signing credentials."},{"stage":"Production & operations","condition":"If operations agents have live credentials."}],"downstreamEffects":[],"theme":"Identity & permissions","crossCutting":true},{"id":"R14","title":"Agent-generated code introduces an exploitable defect","domain":"Coding & tool execution","group":"Coding & tool execution","relevance":"AI-amplified","plainEnglish":"An agent implements a working feature but introduces insecure input handling, authorization bypass, or other latent defects that escape review.","why":"Fast code generation may increase review volume; generated code can appear coherent even when assumptions or security checks are incorrect.","challenge":"Would independent tests and review catch an intentionally planted authorization flaw in generated code?","monitor":"Review defect escape, security findings, rework, coverage, reviewer load and actual time saved.","respond":"Block or roll back unsafe changes, correct the underlying test gap, and update targeted evaluation cases.","stages":["Coding & tool execution"],"riskEvent":"An agent implements a working feature but introduces insecure input handling, authorization bypass, or other latent defects that escape review.","objective":"Generated code must meet the same correctness and security criteria as other code, with validation proportionate to impact.","securityBoundary":"Build and release controls must not treat AI authorship or high model confidence as an authorization substitute.","inspect":"Inspect diff quality, code owners, SAST results, dependency analysis, secure patterns and review evidence.","negativeTest":"Generate a handler with a seeded authorization flaw; test whether validation detects it.","failure":"Passing happy-path tests conceal an exploitable security defect.","evidence":"Security regression results, verified findings, defect escapes, and revision-bound checks.","operations":"Review defect escape, security findings, rework, coverage, reviewer load and actual time saved.","incidentResponse":"Block or roll back unsafe changes, correct the underlying test gap, and update targeted evaluation cases.","approaches":[["Existing engineering checks","Reuse peer review and CI where effective."],["Targeted secure coding tests","Add checks for known high-impact failure patterns."],["Bounded autonomy","Restrict agent changes until defect rates and outcomes justify expansion."]],"sourceStatement":"Fictional feature-writing agent produces a new API endpoint.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Coding & tool execution","otherApplicable":[],"downstreamEffects":["Testing & validation","Review & approval","Build & release","Production & operations"],"theme":"Generated artifact quality","crossCutting":false},{"id":"R15","title":"AI-generated tests repeat the implementation's wrong assumption","domain":"Testing & validation","group":"Testing & validation","relevance":"AI-amplified","plainEnglish":"The same misunderstanding influences both AI-generated code and the tests intended to validate it, so everything passes while a requirement is violated.","why":"Code and tests may share a mistaken interpretation of the task; independent-looking artifacts do not necessarily provide independent verification.","challenge":"Would a test derived from an external acceptance criterion catch a defect that code-generated tests miss?","monitor":"Track seeded defect misses, independent acceptance tests, and failures found after release.","respond":"Add independent test oracles and repair validation gaps before relying on generated test suites.","stages":["Testing & validation","Coding & tool execution"],"riskEvent":"The same misunderstanding influences both AI-generated code and the tests intended to validate it, so everything passes while a requirement is violated.","objective":"Tests for consequential behavior must verify independent acceptance criteria rather than only mirror generated implementation.","securityBoundary":"The test oracle or expected result should not depend solely on the same incorrect model assumptions.","inspect":"Inspect test derivation, requirement traceability, fixture design, mutation testing, and code/test authoring context.","negativeTest":"Seed a specification misunderstanding; ask the agent to produce code and tests, then compare against an independent expected result.","failure":"All generated tests pass despite an important acceptance-condition violation.","evidence":"Independent test oracle, seeded defect results, acceptance criteria, and code coverage limitations.","operations":"Track seeded defect misses, independent acceptance tests, and failures found after release.","incidentResponse":"Add independent test oracles and repair validation gaps before relying on generated test suites.","approaches":[["Human-specified acceptance tests","Anchor critical behavior to stakeholder requirements."],["Independent test-generation context","Separate prompts/inputs and compare disagreements."],["Mutation and adversarial testing","Challenge whether tests detect consequential changes, not just execute lines."]],"sourceStatement":"Fictional agent generates a feature and its matching unit tests.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Testing & validation","otherApplicable":[{"stage":"Coding & tool execution","condition":"If coding agents also generate and validate their own tests."}],"downstreamEffects":["Review & approval","Build & release","Production & operations"],"theme":"Evaluation & test quality","crossCutting":false},{"id":"R16","title":"AI evaluation produces misleading confidence in quality","domain":"Testing & validation","group":"Testing & validation","relevance":"AI-amplified","plainEnglish":"A reviewer or evaluation dashboard reports high agreement or pass rates while missing the errors that matter most.","why":"Models may share context limits, correlated errors, biased examples, or weak ground truth; aggregate scores can conceal severe false negatives.","challenge":"What happens when multiple reviewers miss a known high-severity case, even while overall pass rates are high?","monitor":"Track severe false negatives, disagreements, data-set representativeness and performance across version changes.","respond":"Restrict consequential use when critical evaluation evidence deteriorates; update tests and review scope.","stages":["Testing & validation","Review & approval","Build & release"],"riskEvent":"A reviewer or evaluation dashboard reports high agreement or pass rates while missing the errors that matter most.","objective":"Evaluation must fit the consequential decision, including negative cases and clear severity thresholds.","securityBoundary":"Model agreement or score thresholds alone cannot substitute for independently enforced authorization.","inspect":"Inspect evaluation populations, labels, held-out cases, severity criteria, threshold changes, and false-negative patterns.","negativeTest":"Create a seeded high-impact defect accepted by both AI reviewers; verify the independent gate and escalation.","failure":"A high headline pass rate obscures unacceptable misses.","evidence":"Labeled test corpus, versioned results, adjudication records, and authorization checks.","operations":"Track severe false negatives, disagreements, data-set representativeness and performance across version changes.","incidentResponse":"Restrict consequential use when critical evaluation evidence deteriorates; update tests and review scope.","approaches":[["Advisory evaluation","Keep human review while evidence is immature."],["Risk-stratified cases","Weight severe defects and eligibility failures appropriately."],["Independent verification","Supplement model judgments with executable and domain-grounded tests."]],"sourceStatement":"Fictional AI testing and review pipeline reports 96% pass rate.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Testing & validation","otherApplicable":[{"stage":"Review & approval","condition":"If reviewer AI evaluation results support consequential approvals."},{"stage":"Build & release","condition":"If AI evaluation results authorize releases."}],"downstreamEffects":["Production & operations"],"theme":"Evaluation & test quality","crossCutting":false},{"id":"R17","title":"Agent behavior changes without a corresponding code change","domain":"Testing & validation","group":"Testing & validation","relevance":"Agent-specific","plainEnglish":"An update to model version, prompt, tool schema, context retrieval, or permissions alters decisions or actions without modifying the application code.","why":"The effective engineering workflow depends on more than repository commits; changes in model and tool context can alter behavior.","challenge":"Which non-code changes require fresh evaluation or rollback before the agent continues exercising authority?","monitor":"Detect configuration changes, evaluation regressions, unusual actions and unauthorized tool-scope expansions.","respond":"Restore a known configuration, lower agent authority and re-evaluate before returning to autonomous operation.","stages":["Testing & validation","Design & planning","Coding & tool execution","Review & approval","Build & release","Production & operations"],"riskEvent":"An update to model version, prompt, tool schema, context retrieval, or permissions alters decisions or actions without modifying the application code.","objective":"Material changes to agent behavior and authority should trigger proportionate validation before continued consequential use.","securityBoundary":"Version the decision context and enforce permissions separately from model or prompt configuration.","inspect":"Inspect model/prompt/tool manifests, feature flags, change records, evaluation triggers and rollback capacity.","negativeTest":"Change a tool capability or model version and observe whether required checks rerun before authorization.","failure":"Unreviewed agent configuration changes cause materially different behavior.","evidence":"Config versions, before/after evaluations, approvals, and resulting tool and decision events.","operations":"Detect configuration changes, evaluation regressions, unusual actions and unauthorized tool-scope expansions.","incidentResponse":"Restore a known configuration, lower agent authority and re-evaluate before returning to autonomous operation.","approaches":[["Version and pin dependencies","Control predictable configuration where feasible."],["Risk-triggered reevaluation","Re-test when authority or behavior may change."],["Safe fallback","Revert to advisory or manual operation when validation is incomplete."]],"sourceStatement":"Fictional AI reviewer silently receives a new prompt and additional tool privileges.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Testing & validation","otherApplicable":[{"stage":"Design & planning","condition":"If design agent configurations change behavior."},{"stage":"Coding & tool execution","condition":"If coding agent model, prompts or tools change behavior."},{"stage":"Review & approval","condition":"If reviewer configurations change approval decisions."},{"stage":"Build & release","condition":"If release agent configurations change deployment behavior."},{"stage":"Production & operations","condition":"If operations agent configurations change remediation behavior."}],"downstreamEffects":[],"theme":"Change & configuration integrity","crossCutting":true},{"id":"R01","title":"Agent executes an approval beyond the human instruction","domain":"Delegated authority","riskEvent":"A coding agent can submit GitHub approvals under a person's identity without a revision-bound explicit decision.","objective":"The agent may execute only the specific approval the human authorized for the exact reviewed revision.","securityBoundary":"Separate the human decision from agent execution permissions. Prevent independently initiated approvals or actions on changed commits.","operations":"Investigate anomalous approvals and revoke agent credentials or route to manual review.","approaches":[["Human submits approval","Lowest delegation; higher manual effort."],["Explicit approval instruction","Show exact PR and SHA, record a deliberate human authorization before any tool call."],["Restricted execution gateway","Constrain agents to purpose-bound approval operations; adds gateway maintenance."]],"inspect":"Map the human approval action, GitHub identity, agent tool scopes, tokens and user-session boundaries.","negativeTest":"Ask an agent to approve a different PR or a new revision without a fresh human decision.","failure":"An agent can exercise approval authority that the human did not grant.","evidence":"Human decision artifact, GitHub review event, action trace and exact revision correlation.","incidentResponse":"Flag unexplained approvals, revoke access and require human re-review.","sourceStatement":"Fictional proposal: An engineer decides to approve three stacked PRs and asks an agent to submit them.","refs":["github","ssdf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"You ask an AI agent to submit approval for one specific pull request, but it could approve a different pull request or a newer version that you never reviewed.","group":"Decision & authority","relevance":"Agent-specific","why":"An agent converts human instructions into GitHub tool calls. Its actual execution permissions may exceed the particular approval a human intended.","challenge":"Can the agent approve another PR or revision using the same effective credentials?","monitor":"Reconcile explicit human decisions, revisions, and GitHub approval events; flag unmatched actions.","respond":"Restrict the execution path, investigate unexpected actions and obtain renewed human decisions.","stages":["Review & approval"],"type":"original","primaryStage":"Review & approval","otherApplicable":[],"downstreamEffects":["Build & release"],"theme":"Delegated authority","crossCutting":false},{"id":"R02","title":"AI incorrectly authorizes an ineligible change","domain":"AI decision quality","riskEvent":"The model's assessment contributes authority to submit approval, even when a change is unsafe or out of the eligible population.","objective":"Eligibility is defined independently of the model; uncertain, excluded, failed or disputed cases fall back to accountable human review.","securityBoundary":"An AI score cannot expand the deterministic allowed population or disable exclusions.","operations":"Monitor unsafe approval exceptions, drift, disputes, policy changes and an emergency stop.","approaches":[["Advisory first","Human approval retained while model performance is evaluated."],["Deterministic narrow allowlist","Only validated, bounded change classes can enter an autonomous path."],["Dual independent review","Multiple assessments may reduce some errors but do not replace a hard eligibility boundary."]],"inspect":"Inspect policy/configuration, eligibility truth table, reviewer prompts/models, feature flags and approval integration.","negativeTest":"Submit a prohibited path or hidden shared dependency that AI calls low-risk.","failure":"An unsafe PR receives autonomous approval despite the intended exclusion.","evidence":"Adjudicated false-approval cases, negative test corpus, recorded policy version, decision logs and representative population.","incidentResponse":"Disable active approval, triage impacted merges and change eligibility with reviewed policy.","sourceStatement":"Fictional proposal: eligibility filters and two AI reviewer verdicts must pass before a bot approves.","refs":["ssdf","airmf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"AI says a change is low-risk and approves it, even though that change should have been excluded from automatic approval and reviewed by a person.","group":"Decision & authority","relevance":"AI-amplified","why":"The model's judgment can become the basis for authorization. A classification error matters differently when it determines whether a mandatory review occurs.","challenge":"If AI confidently calls an excluded change safe, what independently prevents approval?","monitor":"Track exclusions, incorrect approvals, reviewer disagreement and configuration changes.","respond":"Suspend autonomous approval if a material incorrect approval is detected; identify affected changes and route to human review.","stages":["Review & approval"],"type":"original","primaryStage":"Review & approval","otherApplicable":[],"downstreamEffects":["Build & release","Production & operations"],"theme":"AI decision reliability","crossCutting":false},{"id":"R03","title":"An exempt automation identity bypasses required authorization","domain":"Authorization enforcement","riskEvent":"The merge or approval service has privileges or exemptions that can circumvent intended GitHub review requirements.","objective":"Required authorization and merge constraints cannot be bypassed by the actor being restricted, including through alternate paths.","securityBoundary":"Who can change rulesets or use an exempt identity? Can the same actor both claim eligibility and bypass enforcement?","operations":"Reconcile exempt merges against authorized decisions; alert on privilege, bypass and ruleset changes.","approaches":[["Retain native required reviews","Do not exempt agents where workflow can be solved through current GitHub protection."],["Narrow purpose-built merge app","Limit identity permissions and enforce eligible SHA/policy before enqueue; independently verify every route."],["Independent authorization gate","Separate policy enforcement from the bot initiating the action; more complexity to operate."]],"inspect":"Inspect GitHub org/repo rulesets, CODEOWNERS, app installation scopes, bypass actors and merge queue behavior.","negativeTest":"Attempt enqueue/merge with an ineligible PR using every available bot or administrative route.","failure":"A bot can merge code that should have required additional authorization.","evidence":"Effective ruleset exports, app permissions, denied bypass attempts, merge queue traces and independent merge population.","incidentResponse":"Suspend the privileged identity, reconcile merges and restore rule enforcement.","sourceStatement":"Fictional proposal: a separate exempt merge identity may enqueue an AI-approved PR.","refs":["github","ssdf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"An automation account has special GitHub permissions that let it approve or merge a change without going through the reviews everyone else must complete.","group":"Decision & authority","relevance":"Foundational dependency","why":"Privileged bypass is not unique to AI. Delegated automation makes it material when an agent can repeatedly exercise permissions that skip intended restrictions.","challenge":"Can a bot both determine eligibility and bypass the rule intended to enforce it?","monitor":"Reconcile privileged merges and changes to exemptions, identities, permissions and rulesets.","respond":"Suspend unsafe privileged paths, investigate affected merges and restore independent enforcement.","stages":["Review & approval","Build & release"],"type":"original","primaryStage":"Review & approval","otherApplicable":[{"stage":"Build & release","condition":"If the exemption also bypasses release authorization."}],"downstreamEffects":["Production & operations"],"theme":"Identity & permissions","crossCutting":false},{"id":"R04","title":"Approval becomes stale after the reviewed revision changes","domain":"Revision integrity","riskEvent":"PR updates, rebase, force push, base-branch changes or stacked dependencies invalidate the content actually reviewed.","objective":"Decision and enforcement bind to the exact reviewable content and require re-evaluation after material changes.","securityBoundary":"Approval invalidation and merge eligibility must be enforced by GitHub or a separately trusted gate.","operations":"Detect changed commits, stale approvals and discrepancy between reviewed and merged revisions.","approaches":[["Manual revision re-review","Human confirms changes after any update."],["Automatic invalidation","Dismiss prior approval for new SHA and rerun applicable checks."],["Commit+dependency binding","Include relevant base and shared dependency state where needed; greater complexity."]],"inspect":"Compare approved SHA/base, merge queue SHA and resulting merge/release artifact.","negativeTest":"Approve revision A, then push revision B or change a stacked dependency before merge.","failure":"The system merges content not covered by the valid approval decision.","evidence":"Revision-bound approval record, invalidation logs and merge checks.","incidentResponse":"Block merge, investigate stale decisions and require renewed authorization.","sourceStatement":"Fictional worked example: shared-library PR may change after risk assessment but before merge.","refs":["github","ssdf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"Someone reviews and approves one version of the code, but the code changes afterward. The newer version could be merged without a fresh review.","group":"Technical scope & reliability","relevance":"AI-amplified","why":"AI evaluations are based on the code and dependencies available at the time. Rebases, stacked changes and subsequent commits can invalidate that basis.","challenge":"After approval, can a changed SHA or dependency reach merge without a new review?","monitor":"Detect changed revisions and discrepancies between reviewed, queued and merged content.","respond":"Block the changed revision until evaluation and authorization are renewed.","stages":["Review & approval","Build & release"],"type":"original","primaryStage":"Review & approval","otherApplicable":[{"stage":"Build & release","condition":"If a revised artifact is built or released using the stale approval."}],"downstreamEffects":["Production & operations"],"theme":"Change & configuration integrity","crossCutting":false},{"id":"R05","title":"Shared-component impact is missed by the local PR assessment","domain":"Dependency impact","riskEvent":"A seemingly narrow change affects downstream dependencies or shared security/financial functions outside the reviewed file list.","objective":"Identify reachable dependencies or conservatively escalate unknown impact instead of assuming local diffs are isolated.","securityBoundary":"Policy and dependency inventory must prevent an AI reviewer from expanding protected scope based on an unverified guess.","operations":"Monitor missed dependency incidents and refresh classification inventories.","approaches":[["Exclude shared libraries","Simple and conservative, potentially reduces automation benefit."],["Dependency-aware screening","Use maintained graphs and impact metadata, fail closed on stale mapping."],["Qualified review for shared code","Require domain expertise for shared components; slower but clearer accountability."]],"inspect":"Inspect dependency maps, shared service ownership, release topology and risk tag coverage.","negativeTest":"Change a shared helper outside a critical file list that alters a protected downstream component.","failure":"A consequential change is incorrectly treated as low-risk because exposure was not detected.","evidence":"Dependency map provenance, counterexample tests and downstream impact traces.","incidentResponse":"Escalate discovered misclassification, revise scope and review affected releases.","sourceStatement":"Fictional worked example: a shared library feeds multiple downstream services.","refs":["ssdf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"A small-looking code change affects other systems because the code is shared. The AI overlooks that broader impact and treats the change as safe.","group":"Technical scope & reliability","relevance":"AI-amplified","why":"A reviewer may reason from a visible diff while missing downstream effects beyond its context. Automated eligibility can turn that incomplete picture into an approval decision.","challenge":"Could a shared helper affecting a protected system still qualify when its file path appears harmless?","monitor":"Review classification misses, stale dependency information and changes to shared code ownership.","respond":"Escalate affected changes; correct dependencies or narrow the automated eligible scope.","stages":["Review & approval","Design & planning"],"type":"original","primaryStage":"Review & approval","otherApplicable":[{"stage":"Design & planning","condition":"If design agents independently decide architectural impact from incomplete dependency context."}],"downstreamEffects":["Coding & tool execution","Build & release","Production & operations"],"theme":"AI decision reliability","crossCutting":false},{"id":"R06","title":"Code or sensitive context is exposed to a third-party reviewer","domain":"Data boundaries","riskEvent":"Source code, PR descriptions, logs or associated data may leave the organization's control through an external AI integration.","objective":"Minimize and authorize transferred content; restrict secrets and sensitive context; assess provider protections and failure dependencies.","securityBoundary":"Review data egress, integration identity, vendor terms, retention and permitted use before sending sensitive material.","operations":"Monitor provider access, egress failures, changes in vendor processing and incident response.","approaches":[["Keep sensitive review local","Less external data exposure, possibly lower model capabilities."],["Redact/minimize payloads","Apply policy-aware filters with realistic bypass testing."],["Approved provider boundary","Contractual/technical restrictions and monitoring; retains third-party dependency."]],"inspect":"Inspect actual data payloads, API configurations, contracts, retention and access controls.","negativeTest":"Include a synthetic secret or sensitive metadata and test whether it is filtered before provider transmission.","failure":"Unauthorized or excessive information reaches a provider or is retained unexpectedly.","evidence":"Payload traces, vendor terms, egress policy and data minimization tests.","incidentResponse":"Disable integration, rotate impacted credentials and escalate data handling event.","sourceStatement":"Fictional proposal: an external AI reviewer may receive PR diffs and comments.","refs":["airmf","ssdf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"An AI review tool receives source code, secrets, logs, or sensitive business information that it was not supposed to receive or retain.","group":"Supporting workflow risks","relevance":"AI-amplified","why":"An external model reviewer can receive broad repository context, issue content and logs. What actually leaves the environment may exceed the intended review scope.","challenge":"What exact content reaches the provider, and can sensitive data or secrets be transmitted?","monitor":"Review egress payloads, integration access, retention terms and provider-processing changes.","respond":"Stop unsafe transfers, rotate affected credentials when warranted and follow the data-incident process.","stages":["Review & approval","Coding & tool execution","Testing & validation"],"type":"original","primaryStage":"Review & approval","otherApplicable":[{"stage":"Coding & tool execution","condition":"If external coding assistants receive sensitive code."},{"stage":"Testing & validation","condition":"If external test agents receive sensitive fixtures or logs."}],"downstreamEffects":[],"theme":"Data & trust boundaries","crossCutting":false},{"id":"R08","title":"Manager routing alters reviewer expertise or authorization","domain":"Behavioral change","riskEvent":"Routing low-risk PRs to managers changes who actually reviews or whose approval satisfies GitHub rules.","objective":"Assignment preserves appropriate technical expertise and does not weaken required authorization unless that substitution is explicitly governed and enforced.","securityBoundary":"Separate reviewer assignment from approval substitution. A routing service should not acquire approval or bypass authority.","operations":"Monitor reassignment, reviewer workload, missed required reviews and prolonged queues.","approaches":[["Existing GitHub reviewer assignment","Try native teams and CODEOWNERS first; minimal new infrastructure."],["Deterministic routing rules","Route according to repo/team ownership; require escalation on unknown classification."],["Policy-based substituted approval","If intentionally reducing code-owner requirements, validate reviewer qualifications and independence explicitly."]],"inspect":"Inspect requested reviewers, GitHub protections, routing conditions, manager roles and baseline review policy.","negativeTest":"Route an out-of-scope PR, unavailable manager or cross-team change and test whether required reviews still block merge.","failure":"An inappropriate reviewer or missing code owner becomes sufficient to merge.","evidence":"Routing rules, reviewer permissions, GitHub rule evaluation and representative review cases.","incidentResponse":"Reassign, restore required review path and investigate skipped expertise.","sourceStatement":"Fictional request: low-risk PRs route to managers who must still review; impact on CODEOWNERS is unspecified.","refs":["github","ssdf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"The workflow sends a change to a manager who may not have the technical expertise or required ownership to review it. Their approval might replace a review that was actually needed.","group":"Supporting workflow risks","relevance":"Foundational dependency","why":"Reviewer routing is not unique to AI. AI-assisted low-risk routing may substitute a convenient approval for the specific technical expertise required.","challenge":"Could a routed manager approval satisfy the rule without a required owner or qualified reviewer?","monitor":"Monitor routing exceptions, absent code owners, substitutions and reviewer availability.","respond":"Restore necessary expert review and investigate incorrectly approved changes.","stages":["Review & approval"],"type":"original","primaryStage":"Review & approval","otherApplicable":[],"downstreamEffects":["Build & release"],"theme":"Review accountability","crossCutting":false},{"id":"R09","title":"Decision records omit failures or cannot be reconciled","domain":"Prompt and tool integrity","riskEvent":"The automation's own logs omit failed, bypassed, retried or out-of-band change activity.","objective":"Independently establish complete populations and reconstruct decisions, revisions, actors and outcomes.","securityBoundary":"Do not rely only on the same automation's success dashboard as evidence of completeness.","operations":"Investigate missing events, retries, drift and unexpected approval/merge rates; maintain human fallback.","approaches":[["Platform audit/event logs","Use authoritative GitHub and CI/CD records instead of only bot logs."],["Reconciliation job","Match merged/deployed changes to decision records and investigate exceptions."],["Independent telemetry","Separate log control and monitoring privileges; higher operating cost."]],"inspect":"Map all decision event types, log retention, audit trail integrity and independent populations.","negativeTest":"Suppress or lose an evaluation event and verify it is surfaced during reconciliation.","failure":"An unauthorized or unsafe change is not visible in the monitored population.","evidence":"Independent merge/deploy populations, event correlation, missing-record exceptions and retention configuration.","incidentResponse":"Raise exception, halt autonomy if material and investigate population completeness.","sourceStatement":"Fictional design: QualityBot provides evaluation decisions and operational dashboards.","refs":["ssdf","airmf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"The monitoring only shows some of what the AI system did. Failed, bypassed, or unusual actions may be missing, so the team could overlook an unsafe change.","group":"Operational assurance","relevance":"Foundational dependency","why":"Automated decision systems can omit failed, retried or bypassed events. Agent autonomy increases the need to check records against outcomes rather than trust the bot's dashboard alone.","challenge":"If an agent action or evaluation event disappears, will independent platform records expose the gap?","monitor":"Reconcile merged and deployed changes against agent decisions, failed events and retries.","respond":"Pause autonomy when missing records prevent reconstruction; investigate the affected population.","stages":["Review & approval","Build & release","Production & operations"],"type":"original","primaryStage":"Review & approval","otherApplicable":[{"stage":"Build & release","condition":"If release agent records are incomplete."},{"stage":"Production & operations","condition":"If operations agent activity records are incomplete."}],"downstreamEffects":[],"theme":"Evidence & observability","crossCutting":false},{"id":"R07","title":"Production contains a change not linked to the reviewed authorization","domain":"Operational visibility","riskEvent":"Alternate deployment paths or missing provenance disconnect approved code from the deployed artifact.","objective":"Trace source revision, valid authorization, build result and production artifact; reconcile independently from the approval bot.","securityBoundary":"A successful GitHub check alone cannot establish all release paths or privileged deployment behavior.","operations":"Reconcile deployed versions with authorized source and investigate unmatched releases.","approaches":[["Use existing CI/CD provenance","Reuse trusted artifact signing, required checks and release controls."],["Independent deployment reconciliation","Compare deployed artifacts to approved merged changes; detection rather than prevention."],["Preventive release authorization","Reject deployments without verified provenance; implementation and availability cost."]],"inspect":"Trace branch, build, package, release and all administrative/emergency paths.","negativeTest":"Attempt deployment from an unapproved commit or altered artifact through an alternate route.","failure":"Production changes despite the apparent PR authorization gate.","evidence":"Complete deployment population, source/build provenance, denied tests and exception reconciliation.","incidentResponse":"Contain release, reconcile versions and invoke rollback or incident response.","sourceStatement":"Fictional workflow: merge may trigger build and production deployment.","refs":["ssdf"],"provenance":"V2 fictional teaching model; illustrative, not verified implementation","plainEnglish":"A change reaches production through a route that is not properly tied to the reviewed and approved code. The team cannot be sure the deployed change was authorized.","group":"Operational assurance","relevance":"Foundational dependency","why":"Production provenance is a longstanding delivery concern. An AI review gate cannot provide end-to-end assurance if another release route bypasses the reviewed revision.","challenge":"Can an unapproved artifact reach production through an emergency or privileged path?","monitor":"Reconcile deployed artifacts and revisions with authorized merges and exceptions.","respond":"Contain unmatched releases, identify the deployed version and execute established recovery procedures.","stages":["Build & release","Production & operations"],"type":"original","primaryStage":"Build & release","otherApplicable":[{"stage":"Production & operations","condition":"If production reconciliation fails to identify the deployed artifact."}],"downstreamEffects":[],"theme":"Release & production integrity","crossCutting":false},{"id":"R18","title":"Build agent alters pipeline or artifact integrity","domain":"Build & release","group":"Build & release","relevance":"Agent-specific","plainEnglish":"An agent with build-system access changes pipeline configuration, dependencies, or artifacts in a way that bypasses intended build and integrity checks.","why":"Build agents and coding agents can reach settings that affect later validation; modifying the guardrail can defeat downstream assurance.","challenge":"Can the agent change the workflow file or artifact after tests pass and still have the build treated as trusted?","monitor":"Track pipeline changes, privileged artifact actions, signatures and untrusted build-context access.","respond":"Quarantine affected artifacts, restore trusted pipeline configuration, and investigate released versions.","stages":["Build & release","Coding & tool execution"],"riskEvent":"An agent with build-system access changes pipeline configuration, dependencies, or artifacts in a way that bypasses intended build and integrity checks.","objective":"Build outcomes and artifacts must be traceable to reviewed source and protected CI configuration.","securityBoundary":"Separate untrusted agent work from privileged signing, CI policy changes and release-authorizing credentials.","inspect":"Inspect CI workflow write permissions, build identities, provenance attestations and artifact promotion constraints.","negativeTest":"Attempt to alter a build workflow or substitute a package after tests using an agent identity.","failure":"A modified pipeline produces an apparently trusted artifact from an unreviewed action.","evidence":"Authoritative source-to-build mapping, workflow revisions, artifact hashes and denied attempts.","operations":"Track pipeline changes, privileged artifact actions, signatures and untrusted build-context access.","incidentResponse":"Quarantine affected artifacts, restore trusted pipeline configuration, and investigate released versions.","approaches":[["Protect CI configuration","Review changes to build and test policy."],["Isolated build identity","Limit repository agent access to protected build credentials."],["Signed promotion","Promote only attributable, validated artifacts."]],"sourceStatement":"Fictional agent manages dependency upgrades and CI scripts.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Build & release","otherApplicable":[{"stage":"Coding & tool execution","condition":"If coding agents have write access to CI workflows."}],"downstreamEffects":["Testing & validation","Production & operations"],"theme":"Release & production integrity","crossCutting":false},{"id":"R19","title":"Release agent deploys beyond approved scope","domain":"Build & release","group":"Build & release","relevance":"Agent-specific","plainEnglish":"An AI release agent starts a production deployment, changes rollout parameters, or overrides a release gate without the required authorization.","why":"An agent's ability to choose and execute release commands can turn a recommendation error into immediate production state change.","challenge":"Can the release agent deploy an unauthorized SHA, environment, or rollback target using its effective credentials?","monitor":"Track release actions, scope drift, approvals, gate denials and actual deployed states.","respond":"Halt releases, restrict execution credentials and invoke rollback or incident procedures.","stages":["Build & release","Production & operations"],"riskEvent":"An AI release agent starts a production deployment, changes rollout parameters, or overrides a release gate without the required authorization.","objective":"Release authority should be externally constrained by approved artifact, environment, window and accountable decision.","securityBoundary":"Separate planning and recommendation from privileged deploy execution, or enforce explicit purpose-bound authorization.","inspect":"Inspect deployment roles, environment protection, approval rules, artifact identity and emergency bypass routes.","negativeTest":"Direct an agent to deploy an excluded artifact or environment; observe independent denial.","failure":"A deployment is triggered despite missing or mismatched authorization.","evidence":"Release event records, artifact digests, authorization context and effective credential mapping.","operations":"Track release actions, scope drift, approvals, gate denials and actual deployed states.","incidentResponse":"Halt releases, restrict execution credentials and invoke rollback or incident procedures.","approaches":[["Manual approval for critical actions","Retain human authority where appropriate."],["Restricted release gateway","Bind executable release to artifact and environment."],["Progressive rollout","Use canaries and rollback paths to contain impact."]],"sourceStatement":"Fictional release agent manages production canary rollouts.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Build & release","otherApplicable":[{"stage":"Production & operations","condition":"If release agents execute live deployment commands."}],"downstreamEffects":[],"theme":"Release & production integrity","crossCutting":false},{"id":"R20","title":"Operations agent makes an unsafe remediation change","domain":"Production & operations","group":"Production & operations","relevance":"Agent-specific","plainEnglish":"An AI operations agent diagnoses an incident incorrectly and restarts services, changes traffic policy, or deletes resources beyond a safe response plan.","why":"An agent can act on incomplete telemetry under time pressure while holding powerful operational credentials.","challenge":"Can a misleading monitoring alert make the agent perform a destructive or unauthorized remediation?","monitor":"Track actions, incident severity, telemetry confidence, emergency escalations and unintended service impact.","respond":"Stop automation, restore safe configuration, invoke incident command and review the action sequence.","stages":["Production & operations","Build & release"],"riskEvent":"An AI operations agent diagnoses an incident incorrectly and restarts services, changes traffic policy, or deletes resources beyond a safe response plan.","objective":"Remediation authority must be constrained by action type, scope, service criticality and rollback ability.","securityBoundary":"Risky production actions require independent policy limits or accountable approval, not only agent self-restraint.","inspect":"Inspect runbooks, role permissions, command allowlists, escalation, rollback and kill-switch enforcement.","negativeTest":"Provide a misleading alert and attempt a destructive production command through the agent's tools.","failure":"Automated remediation amplifies or extends an incident.","evidence":"Authoritative operations logs, incident timeline, policy denials and recovery evidence.","operations":"Track actions, incident severity, telemetry confidence, emergency escalations and unintended service impact.","incidentResponse":"Stop automation, restore safe configuration, invoke incident command and review the action sequence.","approaches":[["Read-only diagnosis","Use AI for investigation without write access."],["Approved runbook executor","Only allow bounded, reversible commands."],["Human escalation","Require incident commander authorization for high-impact actions."]],"sourceStatement":"Fictional on-call agent reacts to an unusual production error rate.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Production & operations","otherApplicable":[{"stage":"Build & release","condition":"If operations agents also execute releases or rollbacks."}],"downstreamEffects":[],"theme":"Operational autonomy & recovery","crossCutting":false},{"id":"R21","title":"Autonomous operations cannot be stopped or investigated","domain":"Production & operations","group":"Production & operations","relevance":"Foundational dependency","plainEnglish":"An agent repeatedly retries harmful actions, monitoring misses them, or engineers cannot reliably disable its access and reconstruct events.","why":"Automated systems always need response capability; agent-initiated action sequences make rapid containment and trustworthy event correlation especially important.","challenge":"If the agent behaves unexpectedly or loses telemetry, can operators halt its actions and reconstruct what actually occurred?","monitor":"Track autonomy disablement, tool calls, incomplete events, retries, manual overrides and recovery success.","respond":"Disable credentials and tool pathways, halt retries and investigate with independent logs.","stages":["Production & operations","Coding & tool execution","Testing & validation","Review & approval","Build & release"],"riskEvent":"An agent repeatedly retries harmful actions, monitoring misses them, or engineers cannot reliably disable its access and reconstruct events.","objective":"Consequential agent actions need observable outcomes, bounded retry behavior, independently operable shutdown and recovery.","securityBoundary":"A model's willingness to stop is not an adequate kill switch for a privileged execution path.","inspect":"Inspect tooling revocation, retries, telemetry sources, alert ownership and restoration procedures.","negativeTest":"Disconnect one telemetry feed, trigger repeated tool failure, and attempt to shut down all execution paths.","failure":"An ongoing unsafe action continues after the operator attempts shutdown.","evidence":"Kill-switch drill results, external action logs, event reconciliation and recovery timeline.","operations":"Track autonomy disablement, tool calls, incomplete events, retries, manual overrides and recovery success.","incidentResponse":"Disable credentials and tool pathways, halt retries and investigate with independent logs.","approaches":[["Read-only or reduced-authority fallback","Continue investigation without production writes."],["Independent execution shutoff","Disable token, runner or gateway outside the model."],["Operational drills","Practice containment and recovery under missing evidence."]],"sourceStatement":"Fictional production agent retries failed remediation while observability is degraded.","refs":["illustrative-engineering-analysis"],"provenance":"New V3 fictional example; design hypothesis, not verified implementation","type":"new","primaryStage":"Production & operations","otherApplicable":[{"stage":"Coding & tool execution","condition":"If coding agents cannot be stopped or actions reconstructed."},{"stage":"Testing & validation","condition":"If test agents cannot be stopped or actions reconstructed."},{"stage":"Review & approval","condition":"If review agents cannot be stopped or actions reconstructed."},{"stage":"Build & release","condition":"If release agents cannot be stopped or actions reconstructed."}],"downstreamEffects":[],"theme":"Operational autonomy & recovery","crossCutting":true}];
